questionvariables.text:
/* Define the data 
X: [6, 2, 15, 9, 12, 5, 8]; 
Y: [82, 86, 43, 74, 58, 90, 78];*/
X:makelist(rand(20),i,1,7); /*Number of absences*/
Y:makelist(rand(100),i,1,7); /*Final grade */
xy:X * Y;
x_sq:X^2;
y_sq:Y^2;
/* Calculate the number of data points (n) */ 
n: length(X);  
/* Calculate the sums of X and Y */ 
sumX: sum(X[i], i, 1, n); 
sumY: sum(Y[i], i, 1, n);  
/* Calculate the sum of the products of X and Y */ 
sumXY: sum(X[i] * Y[i], i, 1, n);  
/* Calculate the sum of the squares of X and Y */ 
sumX2: sum(X[i]^2, i, 1, n); 
sumY2: sum(Y[i]^2, i, 1, n);  
/* Calculate the Pearson correlation coefficient (r) */ 
r1: (n * sumXY - sumX * sumY) / sqrt((n * sumX2 - sumX^2) * (n * sumY2 - sumY^2));  
r:decimalplaces(r1,2);

/*Analysis of r*/
analysis: if r1 > 0 then "There is a positive association between the count of times a student is absent from class and his/her final grades." 
          elseif r1 < 0 then "There is a negative association between the count of times a student is absent from class and his/her final grades." 
         else "No correlation";
ta_2:analysis;
ta_3:if ta_2="There is a positive association between the count of times a student is absent from class and his/her final grades." then "There is a negative association between the count of times a student is absent from class and his/her final grades." elseif ta_2="There is a negative association between the count of times a student is absent from class and his/her final grades." then "There is a positive association between the count of times a student is absent from class and his/her final grades." else "No correlation"; 
ta_23:random_permutation([[ta_2, true],[ta_3, false],["No correlation", false]]);
